    if (action === 'create-invoice') { const j = state.jobs.find(j => j.id === activeJob), form = $('#job-edit-form'), data = Object.fromEntries(new FormData(form)); await api('job-update', { ...data, id: j.id, revision: j.revision, lines: getLines() }); const i = await api('invoice', { jobId: j.id }); render(); openInvoice(i.id); toast('Invoice created.'); }
