const $$ = (s, root = document) => [...root.querySelectorAll(s)];
function updateLiveTotals() { const target = $('#live-totals'); if (target) target.innerHTML = totalsHTML(totals(getLines())); }
document.addEventListener('input', e => { if (e.target.dataset.line) updateLiveTotals(); if (['job-search', 'customer-search'].includes(e.target.id)) { const start = e.target.selectionStart, id = e.target.id; query = e.target.value; render(); const input = $(`#${id}`); input.focus(); input.setSelectionRange(start, start); } });
document.addEventListener('change', e => { if (e.target.id === 'diary-date') { if (e.target.value) diaryDate = e.target.value; render(); } if (e.target.dataset.line) updateLiveTotals(); if (e.target.name === 'customerId' && e.target.closest('#job-form')) { const select = $('[name=vehicleId]', $('#job-form')); select.innerHTML = state.vehicles.filter(v => v.customerId === e.target.value).map(v => `<option value="${v.id}">${esc(v.registration)} · ${esc(v.make)} ${esc(v.model)}</option>`).join('') || '<option value="">Add a vehicle to this customer first</option>'; } });
document.addEventListener('submit', async e => {
  const form = e.target; e.preventDefault();
  if (form.id === 'login-form') {
    if (!form.reportValidity()) return;
    const submit = $('button[type=submit]', form); submit.disabled = true;
    try {
      const data = Object.fromEntries(new FormData(form));
      const result = await fetch('/api/auth/sign-in/email', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
      if (!result.ok) throw new Error('Sign-in failed. Check your details or contact your administrator.');
      form.reset(); await start();
    } catch (err) { error(form, err.message); } finally { submit.disabled = false; }
    return;
  }
  if (form.id === 'global-search') { query = new FormData(form).get('query').trim(); jobFilter = 'all'; route = 'jobs'; location.hash = 'jobs'; render(); return; }
  if (!form.reportValidity()) return;
  const data = Object.fromEntries(new FormData(form)); const submit = $('button[type=submit]', form); if (submit) submit.disabled = true;
  try {
    let result;
    if (form.id === 'job-form') { result = await api('job', { ...data, duration: Number(data.duration), lines: getLines(form) }); render(); openJob(result.id); toast(data.status === 'estimate' ? 'Estimate created.' : 'Booking saved to the diary.'); }
    if (form.id === 'job-edit-form') { const j = state.jobs.find(j => j.id === activeJob); result = await api('job-update', { ...data, id: j.id, revision: j.revision, lines: getLines(form) }); render(); openJob(j.id); toast('Job changes saved.'); }
    if (form.id === 'customer-form') { result = await api('customer', data); render(); openCustomer(result.id); toast('Customer added. Add a vehicle to book them in.'); }
    if (form.id === 'vehicle-form') { await api('vehicle', { ...data, mileage: Number(data.mileage) }); render(); openCustomer(data.customerId); toast('Vehicle added.'); }
    if (form.id === 'product-form') { await api('product', { ...data, stock: Number(data.stock), minimum: Number(data.minimum), cost: Math.round(Number(data.cost) * 100), price: Math.round(Number(data.price) * 100) }); render(); closeModal(); toast('Stock item added.'); }
    if (form.id === 'stock-form') { await api('stock', { ...data, delta: Number(data.delta) }); render(); closeModal(); toast('Stock adjustment recorded.'); }
    if (form.id === 'reminder-form') { await api('reminder', data); render(); closeModal(); toast('Reminder scheduled.'); }
    if (form.id === 'payment-form') { await api('payment', { ...data, amount: Math.round(Number(data.amount) * 100) }); render(); openInvoice(data.invoiceId); toast('Payment recorded.'); }
    if (form.id === 'settings-form') { await api('settings', { ...data, labourRate: Math.round(Number(data.labourRate) * 100) }); render(); toast('Business settings saved.'); }
  } catch (err) { error(form, err.message); } finally { if (submit) submit.disabled = false; }
});
window.addEventListener('hashchange', () => { const next = location.hash.slice(1) || 'today'; if (next !== route) query = ''; route = next; closeModal(); render(); window.scrollTo(0, 0); });
$('#modal').addEventListener('click', e => { if (e.target === $('#modal')) { const rect = e.target.getBoundingClientRect(); if (e.clientX < rect.left || e.clientX > rect.right || e.clientY < rect.top || e.clientY > rect.bottom) closeModal(); } });
function showLogin() {
  $('#app').innerHTML = `<main class="sign-in"><a class="sign-in-brand" href="/">G & J <span>STARKEY</span></a><div class="eyebrow">WORKSHOP MANAGEMENT</div><h1>Welcome back.</h1><p class="subtext">Sign in with your staff account to open the workshop.</p><form id="login-form"><label class="field"><span>Email</span><input type="email" name="email" autocomplete="username" required></label><label class="field"><span>Password</span><input type="password" name="password" autocomplete="current-password" minlength="12" required></label><div class="form-error"></div><button type="submit" class="btn btn-primary">Sign in to the workshop ${icon('arrow')}</button></form><p class="subtext">Staff accounts are created by your system administrator.</p></main>`;
}
async function start() {
  try {
    const permission = await fetch('/api/access');
    if (!permission.ok) throw new Error('Could not check workshop access.');
    access = await permission.json();
    if (!access.authenticated) {
      if (access.configured === false) { $('#app').innerHTML = '<main class="sign-in"><h1>Workshop setup</h1><p class="subtext">The database is connected. Staff sign-in needs configuring before workshop records can be opened.</p></main>'; return; }
      showLogin(); return;
    }
    const response = await fetch('/api/state');
    if (!response.ok) throw new Error(response.status === 401 ? 'Please sign in again.' : 'Could not open the workshop.');
    state = await response.json(); render();
  } catch (err) { $('#app').innerHTML = `<div class="loading"><h1>Workshop unavailable</h1><p>${esc(err.message)} Refresh to try again.</p></div>`; }
}
start();




